const body = $input.first().json.body || {};
const course = body.course || 'Genel';
const message = body.message || 'Merhaba';
const prompt = `Sen üniversite öğrencilerine rehberlik eden Akıllı Bir Ders Asistanısın. Öğrencinin seçtiği ders: ${course}. Soru: ${message}. Soruyu açık, pedagojik, net ve Türkçe olarak yanıtla.`;

const response = await this.helpers.httpRequest({
  method: 'POST',
  url: 'http://ollama:11434/api/generate',
  body: {
    model: 'qwen2.5:3b',
    prompt: prompt,
    stream: false
  },
  json: true
});

return {
  json: {
    success: true,
    reply: (response.response || '').trim(),
    course: course,
    timestamp: new Date().toISOString()
  }
};
